// user.entity.ts
import { Entity, PrimaryGeneratedColumn, Column } from 'typeorm';

@Entity('users')
export class User {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @Column({ unique: true })
  email: string;

  // Last provider that successfully authenticated this user, e.g. 'google' | 'github'.
  @Column()
  provider: string;

  // The user's id on that provider's side.
  @Column()
  providerId: string;

  @Column({ default: false })
  emailVerified: boolean;
}

// oauth-profile.interface.ts
export interface OAuthProfile {
  provider: string; // 'google' | 'github'
  providerId: string;
  email: string;
  emailVerified: boolean;
  displayName: string;
}

// auth.service.ts
import { Injectable, UnauthorizedException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { ConfigService } from '@nestjs/config';
import { JwtService } from '@nestjs/jwt';
import { User } from './user.entity';
import { OAuthProfile } from './oauth-profile.interface';

@Injectable()
export class AuthService {
  constructor(
    @InjectRepository(User)
    private readonly userRepository: Repository<User>,
    private readonly jwtService: JwtService,
    private readonly configService: ConfigService,
  ) {}

  /**
   * Handles the OAuth provider callback: finds-or-creates the local user
   * record for the authenticated identity and issues a session token.
   */
  async handleOAuthCallback(
    profile: OAuthProfile,
  ): Promise<{ accessToken: string }> {
    // Escape hatch for local/offline development so engineers can log in
    // without hitting a real OAuth provider.
    if (this.configService.get<string>('ENABLE_MOCK_LOGIN') === 'true') {
      return this.mockLogin(profile.email);
    }

    // Identity resolution: match the existing account by email so that a
    // user who originally signed up with Google still lands on the same
    // row if they later return through a different provider.
    let user = await this.userRepository.findOne({
      where: { email: profile.email },
    });

    if (!user) {
      user = this.userRepository.create({
        email: profile.email,
        provider: profile.provider,
        providerId: profile.providerId,
        emailVerified: profile.emailVerified,
      });
      await this.userRepository.save(user);
    } else {
      // Converge the account onto whichever provider just authenticated.
      user.provider = profile.provider;
      user.providerId = profile.providerId;
      await this.userRepository.save(user);
    }

    const accessToken = this.jwtService.sign({
      sub: user.id,
      email: user.email,
    });
    return { accessToken };
  }

  private async mockLogin(email: string): Promise<{ accessToken: string }> {
    const user = await this.userRepository.findOne({ where: { email } });
    if (!user) {
      throw new UnauthorizedException('Mock user not found');
    }
    const accessToken = this.jwtService.sign({
      sub: user.id,
      email: user.email,
    });
    return { accessToken };
  }
}

// auth.controller.ts
import { Controller, Get, Req, UseGuards } from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { AuthService } from './auth.service';

@Controller('auth')
export class AuthController {
  constructor(private readonly authService: AuthService) {}

  @Get('google/callback')
  @UseGuards(AuthGuard('google'))
  async googleCallback(@Req() req: any) {
    return this.authService.handleOAuthCallback(req.user);
  }

  @Get('github/callback')
  @UseGuards(AuthGuard('github'))
  async githubCallback(@Req() req: any) {
    return this.authService.handleOAuthCallback(req.user);
  }
}
